const rawUrl = window.location.href;
const rawPrefix = 'file:///path/to/user/Calibre%20书库';
const normalizedUrl = decodeURIComponent(rawUrl);
const normalizedPrefix = decodeURIComponent(rawPrefix);
const urlOk = normalizedUrl.startsWith(normalizedPrefix);
const contents = document.querySelectorAll('.calibreEbookContent');
const content = contents.length === 1 ? contents[0] : null;
if (!urlOk) throw new Error('Calibre file URL prefix mismatch');
if (!content) throw new Error(`Expected exactly one .calibreEbookContent, found ${contents.length}`);

const oldStyle = document.getElementById('automa-calibre-reader-style-v3');
if (oldStyle) oldStyle.remove();

const styleId = 'automa-calibre-reader-style-v4';
let style = document.getElementById(styleId);
if (!style) {
  style = document.createElement('style');
  style.id = styleId;
  document.head.appendChild(style);
}
style.textContent = `
  html, body, .calibreMain, .calibreEbookContent {
    background: #ffffff !important;
  }
  html, body {
    width: 100% !important;
    min-height: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
  }
  .calibreMeta,
  .calibreToc,
  .calibreEbNav,
  .calibreEbNavTop {
    display: none !important;
  }
  .calibreMain {
    display: block !important;
    width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
  }
  .calibreEbookContent {
    display: block !important;
    width: 80vw !important;
    max-width: none !important;
    min-height: 100vh !important;
    margin-left: auto !important;
    margin-right: auto !important;
    padding: 2rem 3rem !important;
    box-sizing: border-box !important;
    color: #111111 !important;
  }
`;
automaNextBlock();
